    /**
     * Method to retrieve the Contact via ContactFetchOneSummary
     * @param 	summary ContactFetchOneSummary 
     * @return 	ContactFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Contact getContact( ContactFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ContactFetchOneSummary arg cannot be null" );
    	
    	Contact entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Contact
        	// --------------------------------------
        	CompletableFuture<Contact> futureEntity = queryGateway.query(new FindContactQuery( new LoadContactFilter( summary.getContactId() ) ), ResponseTypes.instanceOf(Contact.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Contact with id " + summary.getContactId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


